import sys

def sieve(n):
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n**0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    return is_prime

def main():
    n = int(sys.stdin.readline().strip())
    is_prime = sieve(n + 1)

    colors = [0] * (n + 1)
    color_count = 0

    for i in range(2, n + 2):
        if is_prime[i]:
            color_count += 1
            for j in range(i, n + 2, i):
                colors[j] = color_count

    print(color_count)
    print(' '.join(map(str, colors[2:])))

